import os
import hmac
import hashlib
import sqlite3
from flask import Flask, request, jsonify, g
from functools import wraps
import re
import struct

app = Flask(__name__)
app.config['DATABASE'] = '/data/inventory.db'
app.config['HMAC_KEY'] = os.environ.get('HMAC_KEY', 'default-key-change-me')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(app.config['DATABASE'])
        g.db.row_factory = sqlite3.Row
        g.db.execute('PRAGMA journal_mode=WAL')
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('X-Auth-Token', '')
        if len(token) < 32:
            return jsonify({'error': 'unauthorized'}), 401
        # Timing-safe comparison against stored tokens
        db = get_db()
        row = db.execute('SELECT token_hash FROM auth_tokens WHERE active=1 LIMIT 1').fetchone()
        if row is None:
            return jsonify({'error': 'no active tokens'}), 503
        provided_hash = hashlib.sha256(token.encode()).hexdigest()
        if not hmac.compare_digest(provided_hash, row['token_hash']):
            return jsonify({'error': 'unauthorized'}), 401
        return f(*args, **kwargs)
    return decorated

def sanitize_identifier(name):
    """Remove obviously dangerous characters from identifiers.
    Note: this is a defense-in-depth measure, not primary security."""
    # Strip null bytes and control characters
    cleaned = re.sub(r'[\x00-\x1f\x7f]', '', name)
    # Limit length
    return cleaned[:128]

@app.route('/api/v2/inventory/search', methods=['GET'])
@require_auth
def search_inventory():
    """Search inventory with flexible filtering.
    Supports: category, warehouse, sort_field, sort_dir
    """
    category = request.args.get('category', '')
    warehouse = request.args.get('warehouse', '')
    sort_field = request.args.get('sort_field', 'item_name')
    sort_dir = request.args.get('sort_dir', 'ASC')
    page = request.args.get('page', '1')

    # Validate sort direction
    if sort_dir.upper() not in ('ASC', 'DESC'):
        sort_dir = 'ASC'

    # Validate page
    try:
        page_num = max(1, int(page))
    except ValueError:
        page_num = 1

    offset = (page_num - 1) * 50

    # Build query with parameterized WHERE clause
    conditions = []
    params = []

    if category:
        conditions.append('category = ?')
        params.append(category)
    if warehouse:
        conditions.append('warehouse_id = ?')
        params.append(warehouse)

    where_clause = ' AND '.join(conditions) if conditions else '1=1'

    # Sort field validation - allow known columns plus expressions
    allowed_prefixes = ('item_name', 'quantity', 'unit_price', 'last_updated', 
                       'category', 'warehouse_id', 'sku')
    sort_field_clean = sanitize_identifier(sort_field)

    if not sort_field_clean.startswith(allowed_prefixes):
        sort_field_clean = 'item_name'

    # Construct final query
    query = f"""SELECT item_id, sku, item_name, category, quantity, 
                       unit_price, warehouse_id, last_updated 
                FROM inventory 
                WHERE {where_clause} 
                ORDER BY {sort_field_clean} {sort_dir}
                LIMIT 50 OFFSET ?"""

    params.append(offset)

    try:
        db = get_db()
        results = db.execute(query, params).fetchall()
        return jsonify({
            'items': [dict(row) for row in results],
            'page': page_num,
            'sort': sort_field_clean,
            'direction': sort_dir
        })
    except sqlite3.Error as e:
        app.logger.error(f'Database error: {e}')
        return jsonify({'error': 'internal error'}), 500

@app.route('/api/v2/inventory/bulk-update', methods=['POST'])
@require_auth
def bulk_update():
    """Bulk update inventory quantities. Uses parameterized queries."""
    updates = request.get_json()
    if not updates or not isinstance(updates, list):
        return jsonify({'error': 'expected array of updates'}), 400

    db = get_db()
    updated = 0
    for item in updates[:100]:  # Max 100 updates per request
        if 'sku' in item and 'quantity' in item:
            try:
                qty = int(item['quantity'])
                db.execute('UPDATE inventory SET quantity=?, last_updated=CURRENT_TIMESTAMP WHERE sku=?',
                          (qty, item['sku']))
                updated += 1
            except (ValueError, sqlite3.Error):
                continue
    db.commit()
    return jsonify({'updated': updated})

